import hashlib,json,time
from confluent_kafka import Producer,TopicCollection
from confluent_kafka.admin import AdminClient,ConfigResource,ConfigEntry,ResourceType,AlterConfigOpType

def recover(bootstrap,name,expected_id,snapshot,approval):
    digest=hashlib.sha256(json.dumps({k:v.hex() for k,v in snapshot.items()},sort_keys=True,separators=(',',':')).encode()).hexdigest()
    if approval!={'topic':name,'topic_id':expected_id,'snapshot_sha256':digest,'action':'retain-latest-and-restore'}:raise ValueError('exact identity and snapshot approval required')
    admin=AdminClient({'bootstrap.servers':bootstrap,'log_level':0})
    actual=str(admin.describe_topics(TopicCollection([name]))[name].result(5).topic_id)
    if actual!=expected_id:raise ValueError('topic incarnation changed')
    target=ConfigResource(ResourceType.TOPIC,name,incremental_configs=[ConfigEntry('cleanup.policy','compact',incremental_operation=AlterConfigOpType.SET)])
    admin.incremental_alter_configs([target])[target].result(5)
    resource=ConfigResource(ResourceType.TOPIC,name);deadline=time.monotonic()+5
    while time.monotonic()<deadline:
        if admin.describe_configs([resource])[resource].result(5)['cleanup.policy'].value=='compact':break
        time.sleep(.05)
    else:raise TimeoutError('approved policy not observed')
    producer=Producer({'bootstrap.servers':bootstrap,'log_level':0,'linger.ms':0});errors=[]
    for key,value in sorted(snapshot.items()):producer.produce(name,key=key.encode(),value=value,partition=0,on_delivery=lambda error,message:errors.append(error))
    if producer.flush(5)!=0 or len(errors)!=len(snapshot) or any(errors):raise RuntimeError('snapshot publication incomplete')
    return {'topic_id':actual,'snapshot_sha256':digest,'restored':len(snapshot)}
