"""Actual Kafka log scan, topic config and retention witness helpers; no mocked records."""
import json,time
from confluent_kafka import Producer,TopicPartition,KafkaError
from confluent_kafka.admin import ConfigResource,ConfigEntry,ResourceType,AlterConfigOpType
from native import consumer

def describe(admin,name):
 r=ConfigResource(ResourceType.TOPIC,name)
 return admin.describe_configs([r])[r].result(5)

def change(admin,name,key,value):
 r=ConfigResource(ResourceType.TOPIC,name,incremental_configs=[ConfigEntry(key,value,incremental_operation=AlterConfigOpType.SET)])
 admin.incremental_alter_configs([r])[r].result(5)

def send(bootstrap,name,values):
 producer=Producer({'bootstrap.servers':bootstrap,'log_level':0,'linger.ms':0})
 errors=[]
 for key,value in values.items():producer.produce(name,key=key.encode(),value=value,partition=0,on_delivery=lambda error,message:errors.append(error))
 assert producer.flush(5)==0 and len(errors)==len(values) and not any(errors)

def scan(bootstrap,name):
 client=consumer(bootstrap);rows=[]
 try:
  low,high=client.get_watermark_offsets(TopicPartition(name,0),timeout=4,cached=False)
  client.assign([TopicPartition(name,0,low)])
  deadline=time.monotonic()+3
  while time.monotonic()<deadline:
   msg=client.poll(.05)
   if msg is None:continue
   if msg.error():
    if msg.error().code()==KafkaError._PARTITION_EOF and msg.offset()>=high:return rows,low,high
    raise AssertionError('unexpected native Kafka read error: '+str(msg.error()))
   if msg.offset()>=high:return rows,low,high
   rows.append((msg.key().decode(),msg.value(),msg.offset()))
   if msg.offset()+1>=high:return rows,low,high
  if low==high:return rows,low,high
  raise AssertionError('native frozen log range EOF not reached')
 finally:client.close()

def latest_business(bootstrap,name):
 rows,low,high=scan(bootstrap,name);state={}
 for key,value,_ in rows:
  if key.startswith('business/'):
   if value is None:state.pop(key,None)
   else:state[key]=value
 return state,low,high

def expire_latest(bootstrap,admin,name,snapshot):
 send(bootstrap,name,snapshot)
 before,low,high=latest_business(bootstrap,name);assert before==snapshot
 change(admin,name,'retention.ms','1000')
 deadline=time.monotonic()+12;rounds=0
 while time.monotonic()<deadline:
  time.sleep(.3);send(bootstrap,name,{'fixture/tick':('roll-'+str(rounds)).encode()});rounds+=1
  state,after_low,after_high=latest_business(bootstrap,name)
  if not state:
   assert after_low>low
   print('NATIVE_KAFKA_COMPACT_DELETE_ACTUALLY_REMOVED_EACH_BUSINESS_KEYS_LATEST_VALUE:'+json.dumps({'initial_low':low,'initial_high':high,'after_low':after_low,'after_high':after_high,'rounds':rounds}),flush=True)
   return
 raise AssertionError('native TTL did not actually remove latest business values')
